from django.conf import settings

def generate_username(email, claims=None):
    # taken from mozilla-django-oidc docs :)

    # Using Python 3 and Django 1.11+, usernames can contain alphanumeric
    # (ascii and unicode), _, @, +, . and - characters. So we normalize
    # it and slice at 150 characters.
    if claims is None:
        claims = {}

    claim_name = getattr(settings, "OIDC_USERNAME_CLAIM", "email")

    candidate = None
    if isinstance(claims, dict):
        candidate = claims.get(claim_name)

    if not candidate:
        candidate = email

    candidate = "" if candidate is None else str(candidate)
    return unicodedata.normalize("NFKC", candidate)[:150]

